{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C08", "C47", "C12", "C18", "C03", "C70", "C75", "C83", "C86", "C93", "C100", "C109", "C65", "C73", "C84", "C99", "C63", "C66", "C61", "C101", "C102", "C108"],
  "contradictory_card_ids": ["C27", "C60", "C94"],
  "prediction_basis_card_ids": ["C08", "C47", "C12", "C18", "C03", "C70", "C75", "C83", "C86", "C93", "C100", "C109"],
  "claims": [
    {
      "claim": "KNI-272, the closest HIV protease inhibitor context sharing the tert-butyl amide and thioether features of the query, had absolute oral bioavailability of 36.4% as a post-prandial capsule in patients, directly supporting F at or above 20% under fed conditions.",
      "card_ids": ["C08"]
    },
    {
      "claim": "The same KNI-272 fed context gave F of 22.06 percent at a 4 mg/kg capsule dose, still above threshold, while the 2 mg/kg cherry syrup gave 15.72 percent, showing formulation and dose dependence rather than a class-level low outcome.",
      "card_ids": ["C47", "C27"]
    },
    {
      "claim": "Atazanavir, an HIV protease inhibitor, has oral bioavailability above 90% when taken with food, providing strong fed-state class support.",
      "card_ids": ["C12", "C18"]
    },
    {
      "claim": "Paritaprevir, a peptidomimetic protease inhibitor, had absolute oral bioavailability of 52.6% from a tablet, further supporting adequate F for this compound class.",
      "card_ids": ["C03", "C24", "C54"]
    },
    {
      "claim": "L3 oral exposure records show HIV protease inhibitors achieve substantial human Cmax and AUC values, including boosted saquinavir Cmax 3.1 to 8.85 µg/ml and AUC 35 to 82 µg h/ml, atazanavir Cmax 2.92 to 5.27 and AUC 28.8 to 47, indinavir Cmax 7.61 to 13.4, darunavir Cmax 5.3, and amprenavir AUC 23.49 to 47.11, confirming meaningful oral absorption for this peptidomimetic scaffold.",
      "card_ids": ["C70", "C75", "C83", "C86", "C93", "C100", "C109", "C65", "C73", "C84", "C99", "C63", "C66", "C61", "C101", "C102", "C108"]
    },
    {
      "claim": "Unboosted saquinavir shows low exposure with Cmax 0.90 µg/ml and AUC 4.60 µg h/ml, but the query is not saquinavir and the fed condition plus closer structural analogs KNI-272 and atazanavir support higher F.",
      "card_ids": ["C109", "C60", "C94"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C61", "C63", "C65", "C66", "C70", "C73", "C75", "C83", "C84", "C86", "C93", "C99", "C100", "C101", "C102", "C108", "C109"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "Most L3 exposures were measured with ritonavir boosting, while the query has no co-treatment specified.",
    "Unboosted saquinavir low exposure shows class variability in first-pass metabolism that is not resolved for the query.",
    "KNI-272 fed-state F rests on only two patients and shows formulation dependence.",
    "Query-specific fed solubility, permeability, and first-pass extraction are not directly measured."
  ],
  "decision_summary": "The L3 oral exposure records for the HIV protease inhibitor class demonstrate substantial human oral Cmax and AUC, confirming meaningful absorption for this peptidomimetic scaffold. Combined with the closest fed context KNI-272 capsule F of 36.4% and atazanavir with food above 90%, the high prediction is supported. The below-threshold KNI-272 syrup result and unboosted saquinavir exposures are formulation or boosting specific and do not provide affirmative F below 20% evidence for the query. The high prediction is strengthened with moderate confidence."
}

